const body = $json.body || {};

const question = body.question || body.query || body.message;

if (!question || String(question).trim().length === 0) {
  throw new Error('Question is required. Send JSON body like: { "question": "..." }');
}

return {
  json: {
    question: String(question).trim()
  }
};

const input = $input.first().json;

const question = String(
  input.question || input.body?.question || ''
).trim();

if (!question) {
  throw new Error('Question is required.');
}

const normalized = question
  .toLocaleLowerCase('tr-TR')
  .replace(/[!?.,:;]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const greetingWords = [
  'merhaba',
  'selam',
  'selamlar',
  'iyi günler',
  'günaydın',
  'iyi akşamlar',
  'iyi çalışmalar'
];

const identityPatterns = [
  'sen kimsin',
  'kimsin',
  'nesin',
  'adın ne',
  'kendini tanıt',
  'kendini tanıtır mısın'
];

const capabilityPatterns = [
  'ne yapabiliyorsun',
  'neler yapabiliyorsun',
  'ne işe yarıyorsun',
  'hangi konularda yardımcı olabilirsin',
  'hangi konularda yardımcı oluyorsun',
  'bana nasıl yardımcı olabilirsin',
  'ne konuda yardımcı olabilirsin'
];

const thanksPatterns = [
  'teşekkürler',
  'teşekkür ederim',
  'sağ ol',
  'sağol',
  'eyvallah'
];

const clearlyOutOfScopePatterns = [
  'yemek tarifi',
  'tarif verir misin',
  'ne yemek',
  'hava durumu',
  'bugün hava',
  'maç sonucu',
  'spor',
  'film öner',
  'dizi öner',
  'müzik öner',
  'şarkı öner',
  'şiir yaz',
  'hikaye yaz',
  'fıkra anlat',
  'şaka yap',
  'borsa',
  'kripto',
  'bitcoin',
  'tatil öner',
  'otel öner',
  'uçak bileti',
  'matematik sorusu',
  'denklem çöz',
  'çeviri yap',
  'ingilizceye çevir',
  'python kodu',
  'kod yazar mısın',
  'programlama ödevi',
  'javascript kodu',
  'java kodu',
  'c# kodu'
];

function includesAny(patterns) {
  return patterns.some((pattern) => normalized.includes(pattern));
}

let staticAnswer = null;

if (greetingWords.includes(normalized)) {
  staticAnswer =
    'Merhaba, ben İZELTAŞ IT Danışma Asistanı’yım. VPN, şifre, Outlook, yazıcı, donanım, ağ bağlantısı ve ekipman talepleri gibi IT konularında yardımcı olabilirim.';
}

if (!staticAnswer && includesAny(identityPatterns)) {
  staticAnswer =
    'Ben İZELTAŞ IT Danışma Asistanı’yım. Lokal LLM ve RAG yapısıyla, yüklenen IT destek dokümanlarına göre kullanıcılara yardımcı olmak için tasarlandım.';
}

if (!staticAnswer && includesAny(capabilityPatterns)) {
  staticAnswer =
    'VPN bağlantısı, şifre işlemleri, Outlook sorunları, yazıcı problemleri, donanım destekleri, ağ bağlantısı, ortak klasör erişimi ve ekipman talepleri hakkında yardımcı olabilirim.';
}

if (!staticAnswer && includesAny(thanksPatterns)) {
  staticAnswer =
    'Rica ederim. IT süreçleriyle ilgili başka bir konuda da yardımcı olabilirim.';
}

const isClearlyOutOfScope = includesAny(clearlyOutOfScopePatterns);

// Yeni mantık:
// Statik cevap yoksa ve bariz kapsam dışı değilse RAG'e gönder.
const isSupportedTopic = !staticAnswer && !isClearlyOutOfScope;

const outOfScopeAnswer =
  'Bu konuda yardımcı olamam. Ben yalnızca VPN, şifre işlemleri, Outlook, yazıcı, donanım, ağ bağlantısı, ortak klasör erişimi, yazılım yetkisi ve ekipman talepleri gibi IT destek konularında yardımcı olabilirim.';

return [
  {
    json: {
      question,
      is_static_response: Boolean(staticAnswer),
      is_supported_topic: Boolean(isSupportedTopic),
      answer: staticAnswer || outOfScopeAnswer,
      sources: []
    }
  }
];

const items = $input.all();
const intentData = $('Detect Simple Intent').first().json;

const question = String(intentData.question || '').trim();

// ============================================================
// AYARLAR
// ============================================================


const ENABLE_SCORE_THRESHOLD = true;
const LOWER_SCORE_IS_BETTER = true;


const SCORE_THRESHOLD = 0.50;

const MAX_SOURCES = 1;

// ============================================================
// YARDIMCI FONKSİYONLAR
// ============================================================

function parseMetadata(value) {
  if (!value) {
    return {};
  }

  if (typeof value === 'object') {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
}

function getContent(row) {
  return String(
    row.pageContent ||
    row.content ||
    row.text ||
    row.document?.pageContent ||
    row.document?.content ||
    row.document?.text ||
    row.json?.pageContent ||
    row.json?.content ||
    row.json?.text ||
    ''
  ).trim();
}

function getMetadata(row) {
  return parseMetadata(
    row.metadata ||
    row.document?.metadata ||
    row.json?.metadata ||
    {}
  );
}

function getScore(row) {
  const value =
    row.score ??
    row.distance ??
    row.json?.score ??
    row.json?.distance ??
    row.document?.score ??
    row.document?.distance ??
    null;

  if (value === null || value === undefined) {
    return null;
  }

  const numberValue = Number(value);

  if (Number.isNaN(numberValue)) {
    return null;
  }

  return numberValue;
}

function isScoreAccepted(score) {
  if (!ENABLE_SCORE_THRESHOLD) {
    return true;
  }

  if (score === null) {
    return false;
  }

  if (LOWER_SCORE_IS_BETTER) {
    return score <= SCORE_THRESHOLD;
  }

  return score >= SCORE_THRESHOLD;
}

function compareScores(firstDocument, secondDocument) {
  const firstScore = firstDocument.score;
  const secondScore = secondDocument.score;

  if (firstScore === null && secondScore === null) {
    return 0;
  }

  if (firstScore === null) {
    return 1;
  }

  if (secondScore === null) {
    return -1;
  }

  if (LOWER_SCORE_IS_BETTER) {
    return firstScore - secondScore;
  }

  return secondScore - firstScore;
}

// ============================================================
// N8N ÇIKTILARINI TEK LİSTEYE DÖNÜŞTÜR
// ============================================================

const documents = [];

for (const item of items) {
  const row = item.json || {};

  if (Array.isArray(row.documents)) {
    for (const document of row.documents) {
      documents.push(document);
    }

    continue;
  }

  if (Array.isArray(row.results)) {
    for (const document of row.results) {
      documents.push(document);
    }

    continue;
  }

  documents.push(row);
}

// ============================================================
// ADAY DOKÜMANLARI HAZIRLA
// ============================================================

const candidateDocuments = documents
  .map((document, index) => {
    return {
      content: getContent(document),
      metadata: getMetadata(document),
      score: getScore(document),
      original_index: index
    };
  })
  .filter((document) => document.content.length > 20)
  .sort(compareScores);

// Önce threshold filtresi uygulanır.
// Ardından en iyi en fazla 2 kaynak alınır.
//
// Burada 2 kaynak bulunması zorunlu değildir.
// Bir tane uygun kaynak varsa cevap üretilebilir.
const usefulDocuments = candidateDocuments
  .filter((document) => isScoreAccepted(document.score))
  .slice(0, MAX_SOURCES);

// ============================================================
// LLM CONTEXT HAZIRLA
// ============================================================

const context = usefulDocuments.length > 0
  ? usefulDocuments
      .map((document, index) => {
        const metadata = document.metadata || {};
        const sectionTitle = metadata.section_title || '';

        return [
          `[PASSAGE ${index + 1}]`,
          sectionTitle ? `TOPIC: ${sectionTitle}` : '',
          document.content
        ]
          .filter(Boolean)
          .join('\n');
      })
      .join('\n\n---\n\n')
  : 'NO_RELEVANT_SOURCE';

// ============================================================
// FRONTEND'E DÖNECEK KAYNAKLAR
// ============================================================

const sources = usefulDocuments.map((document, index) => {
  const metadata = document.metadata || {};

  return {
    document_id: metadata.document_id || null,
    title: metadata.title || null,
    category: metadata.category || null,
    section_title: metadata.section_title || null,
    chunk_index: metadata.chunk_index ?? index + 1,
    source_file_name: metadata.source_file_name || null,
    file_type: metadata.file_type || null,
    score: document.score
  };
});

// ============================================================
// PROMPT
// ============================================================

const prompt = `
You are an internal IT support assistant for İZELTAŞ.

The PASSAGE below has already been selected as relevant to the USER QUESTION.

Answer the USER QUESTION using only the information explicitly stated in the PASSAGE.

SOURCE RULES:

- Use only information contained in the PASSAGE.
- Do not use outside knowledge.
- Do not invent, infer or complete missing troubleshooting steps.
- Preserve the original meaning of every source statement.
- Never reverse the meaning of a sentence.
- Never convert a warning, possible cause, risk or negative consequence into an instruction.
- A statement such as "X may cause a problem" does not mean that the user should do X.
- Preserve important conditions such as "if the problem continues".
- Do not add an IT support step unless the PASSAGE explicitly contains that step.
- Prefer minimal rewriting instead of creative rewriting.

TARGET RULES:

- Answer only for the exact device, application, system or problem named in the USER QUESTION.
- Do not replace the target with a related device or sibling topic.
- Do not assume that the user performed an action unless the USER QUESTION explicitly says so.
- Select only the instructions that apply to the user's stated situation.

LANGUAGE AND STYLE:

- Write in Turkish only.
- Use clear, grammatically correct and natural Turkish.
- Prefer short Turkish sentences that remain close to the wording of the PASSAGE.
- Address the user directly when this can be done without changing the source meaning.
- Use direct instructions such as "kontrol edin", "güncelleyin" or "başvurun" only when the meaning can be preserved safely.
- Passive wording is acceptable when rewriting could change the meaning.
- Express conditions using natural Turkish forms such as "Sorun devam ederse, ...".
- Do not combine conflicting conditional forms such as "eğer ... devam ettiğinde".
- Never begin a bullet point with "Kullanıcı".
- Do not refer to the user in the third person.
- Do not repeat or rephrase the USER QUESTION.
- Do not mention the passage, source, document, section, metadata, chunk or score.

ANSWER FORMAT:

- Return between 1 and 3 bullet points.
- Start every bullet point with "- ".
- Include the most relevant and useful actions first.
- Each bullet point must contain one distinct instruction.
- A bullet may contain two closely connected actions when they are presented together in the PASSAGE.
- Do not add actions only to reach 3 bullet points.
- Do not repeat the same instruction using different wording.
- Do not write an introduction or conclusion.
- Do not ask a follow-up question.

FINAL CHECK:

- Every bullet must directly apply to the USER QUESTION.
- Every instruction must be explicitly supported by the PASSAGE.
- Preserve conditional expressions such as "sorun devam ederse".
- Do not reverse warnings, causes or negative consequences.
- Make sure every Turkish sentence is complete and understandable.

PASSAGE:

${context}

USER QUESTION:

${question}

Return only the Turkish bullet points.
`;


// ============================================================
// DEBUG BİLGİLERİ
// ============================================================

const debug = {
  threshold_enabled: ENABLE_SCORE_THRESHOLD,
  threshold: SCORE_THRESHOLD,
  lower_score_is_better: LOWER_SCORE_IS_BETTER,
  candidate_count: candidateDocuments.length,
  accepted_count: usefulDocuments.length,

  candidate_documents: candidateDocuments.map((document) => {
    return {
      document_id: document.metadata?.document_id || null,
      title: document.metadata?.title || null,
      section_title: document.metadata?.section_title || null,
      score: document.score,
      accepted: isScoreAccepted(document.score)
    };
  })
};

// ============================================================
// N8N ÇIKIŞI
// ============================================================

return [
  {
    json: {
      question,
      context,
      prompt,
      sources,
      debug
    }
  }
];

const buildPromptOutput = $('Build Prompt').first().json;

const question = String(buildPromptOutput.question || '').trim();

const sources = Array.isArray(buildPromptOutput.sources)
  ? buildPromptOutput.sources
  : [];

const context = String(buildPromptOutput.context || '').trim();

const noRelevantSourceAnswer =
  '- Bu konuda kaynak dokümanlarda yeterli bilgi bulamadım. IT destek ekibiyle iletişime geçebilirsiniz.';

const llmErrorAnswer =
  '- Şu anda yapay zeka modeli yanıt veremiyor. Lütfen daha sonra tekrar deneyin veya IT destek ekibiyle iletişime geçin.';

// ============================================================
// 1. BUILD PROMPT TARAFINDA KAYNAK BULUNAMADI
// ============================================================

if (sources.length === 0 || context === 'NO_RELEVANT_SOURCE') {
  return {
    json: {
      question,
      answer: noRelevantSourceAnswer,
      sources: [],
      response_type: 'no_relevant_source'
    }
  };
}

// ============================================================
// 2. LLM CHAIN NODE HATASI
// ============================================================

// Generate Answer node'u "On Error: Continue" kullanıyorsa
// teknik hata çıktıları burada yakalanır.
const hasNodeError =
  Boolean($json.error) ||
  Boolean($json.stack) ||
  Boolean(
    $json.message &&
    String($json.message)
      .toLocaleLowerCase('tr-TR')
      .includes('error')
  );

if (hasNodeError) {
  return {
    json: {
      question,
      answer: llmErrorAnswer,
      sources,
      response_type: 'llm_error'
    }
  };
}

// ============================================================
// 3. LLM CEVABINI AL
// ============================================================

const rawAnswer = String(
  $json.text ??
  $json.output ??
  $json.response ??
  $json.answer ??
  $json.result ??
  $json.data?.text ??
  $json.data?.output ??
  ''
).trim();

if (!rawAnswer) {
  return {
    json: {
      question,
      answer: llmErrorAnswer,
      sources,
      response_type: 'llm_error'
    }
  };
}

// ============================================================
// 4. NO_RELEVANT_SOURCE KONTROLÜ
// ============================================================

function cleanSentinelOutput(text) {
  return String(text || '')
    .replace(/```(?:text|plaintext)?/gi, '')
    .replace(/```/g, '')
    .replace(/^["'`]+|["'`]+$/g, '')
    .trim();
}

const cleanedRawAnswer = cleanSentinelOutput(rawAnswer);

// Model yalnızca sentinel değerini döndürmüşse yakala.
// Küçük/büyük harf ve sondaki nokta kabul edilir.
const isNoRelevantSource =
  /^NO_RELEVANT_SOURCE[.!]?$/i.test(cleanedRawAnswer);

if (isNoRelevantSource) {
  return {
    json: {
      question,
      answer: noRelevantSourceAnswer,
      sources: [],
      response_type: 'no_relevant_source'
    }
  };
}

// ============================================================
// 5. TEMEL METİN DÜZELTMELERİ
// ============================================================

function fixBasicFormatting(text) {
  return String(text || '')
    .replace(/:\./g, '.')
    .replace(/\s+\./g, '.')
    .replace(/[ \t]+/g, ' ')
    .replace(/Kurulum tarafından/g, 'Kurum tarafından')
    .replace(/kurulum tarafından/g, 'kurum tarafından')
    .trim();
}

function isInvalidLine(text) {
  const normalized = String(text || '')
    .toLocaleLowerCase('tr-TR')
    .trim();

  const invalidPatterns = [
    'source text',
    'source',
    'kaynak metin',
    'metadata',
    'chunk',
    'document_id',
    'section title',
    'bölüm başlığı',
    'final answer',
    'final cevap',
    'aşağıdaki adımları',
    'şu adımları',
    'bu sorunu çözmek için',
    'bu bölümde',
    'cevap veriyorum',
    'yönlendiriyorum'
  ];

  return invalidPatterns.some((pattern) =>
    normalized.includes(pattern)
  );
}

// Maddeleri karşılaştırmak için normalize eder.
// Sadece noktalama ve boşluk farklarını yok sayar.
function createBulletComparisonKey(text) {
  return String(text || '')
    .toLocaleLowerCase('tr-TR')
    .replace(/[.!?,;:]+/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// ============================================================
// 6. MADDE FORMATINA DÖNÜŞTÜR
// ============================================================

function normalizeBullets(answer) {
  const cleaned = fixBasicFormatting(answer);

  if (!cleaned) {
    return {
      success: false,
      answer: llmErrorAnswer
    };
  }

  const lines = cleaned
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);

  // Önce modelin doğrudan ürettiği madde işaretlerini kullan.
  let bulletLines = lines.filter((line) =>
    /^[-•*]\s+/.test(line)
  );

  // Madde işareti yoksa cümleleri maddelere dönüştür.
  if (bulletLines.length === 0) {
    const sentences = cleaned
      .split(/(?<=[.!?])\s+/)
      .map((sentence) => sentence.trim())
      .filter(Boolean);

    bulletLines = sentences.map(
      (sentence) => `- ${sentence}`
    );
  }

  bulletLines = bulletLines
    .map((line) =>
      line.replace(/^[-•*]\s+/, '').trim()
    )
    .map(fixBasicFormatting)
    .filter((line) => line.length > 0)
    .filter((line) => !isInvalidLine(line));

  // ==========================================================
  // TEKRAR EDEN MADDELERİ TEMİZLE
  // ==========================================================

  const seenBullets = new Set();

  bulletLines = bulletLines.filter((line) => {
    const comparisonKey =
      createBulletComparisonKey(line);

    if (!comparisonKey) {
      return false;
    }

    if (seenBullets.has(comparisonKey)) {
      return false;
    }

    seenBullets.add(comparisonKey);
    return true;
  });

  // Kaynak bulunduğu hâlde kullanılabilir cevap üretilemediyse
  // bunu no_relevant_source değil, llm_error olarak değerlendir.
  if (bulletLines.length === 0) {
    return {
      success: false,
      answer: llmErrorAnswer
    };
  }

  const normalizedAnswer = bulletLines
    .slice(0, 3)
    .map((line) => {
      let text = fixBasicFormatting(line);

      if (!/[.!?]$/.test(text)) {
        text += '.';
      }

      return `- ${text}`;
    })
    .join('\n');

  return {
    success: true,
    answer: normalizedAnswer
  };
}

// ============================================================
// 7. CEVABI FORMATLA
// ============================================================

const normalizedResult =
  normalizeBullets(cleanedRawAnswer);

if (!normalizedResult.success) {
  return {
    json: {
      question,
      answer: normalizedResult.answer,
      sources,
      response_type: 'llm_error'
    }
  };
}

// ============================================================
// 8. BAŞARILI RAG CEVABI
// ============================================================

return {
  json: {
    question,
    answer: normalizedResult.answer,
    sources,
    response_type: 'rag_answer'
  }
};

const chatData = $('Prepare Chat Log Data').first().json;

return {
  json: {
    question: chatData.question,
    answer: chatData.answer,
    sources: chatData.sources || [],
    response_type: chatData.response_type || "unknown"
  }
};

const question = $json.question;

return {
  json: {
    question,
    answer: '- Bu konuda kaynak dokümanlarda yeterli bilgi bulamadım. IT destek ekibiyle iletişime geçebilirsiniz.',
    sources: [],
    response_type: 'no_relevant_source'
  }
};

const question = String($json.question || '').trim();
const answer = String($json.answer || '').trim();
const sources = Array.isArray($json.sources) ? $json.sources : [];

if (!question) throw new Error('Question is required for chat log.');
if (!answer) throw new Error('Answer is required for chat log.');

function maskSensitiveText(value) {
  return String(value ?? '')
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[masked_email]')
    .replace(/(\+90|0)?\s?5\d{2}\s?\d{3}\s?\d{2}\s?\d{2}/g, '[masked_phone]')
    .replace(/\b\d{8,}\b/g, '[masked_number]');
}

const firstSource = sources[0] || {};

const category = firstSource.category || null;
const sectionTitle = firstSource.section_title || null;

const responseType =
  $json.response_type ||
  (sources.length > 0 ? 'rag_answer' : 'unknown');

const maskedQuestion = maskSensitiveText(question);
const maskedAnswer = maskSensitiveText(answer);

return {
  json: {
    question,
    answer,
    sources,

    question_masked: maskedQuestion,
    answer_masked: maskedAnswer,

    // JSONB alanı için array'i object içine alıyoruz.
    sources_json: {
      source_items: sources
    },

    category,
    section_title: sectionTitle,
    response_type: responseType
  }
};

const intentData = $('Detect Simple Intent').first().json;

return {
  json: {
    question: intentData.question,
    answer: intentData.answer,
    sources: [],
    response_type: "out_of_scope"
  }
};
